methods::setClass("DistanceRoot", slots = c(value = "numeric"))
methods::setClass("DistanceParent", contains = "DistanceRoot")
methods::setClass("DistanceChild", contains = "DistanceParent")
methods::setGeneric("s4Distance", function(x, y) standardGeneric("s4Distance"))
methods::setMethod("s4Distance", c("DistanceRoot", "ANY"), function(x, y) "root")
methods::setMethod("s4Distance", c("DistanceParent", "ANY"), function(x, y) "parent")
methods::setMethod("s4Distance", c("DistanceParent", "missing"), function(x, y) "missing")

methods::setClass("Left", slots = c(left = "numeric"))
methods::setClass("Right", slots = c(right = "numeric"))
methods::setClass("Both", contains = c("Left", "Right"))
methods::setGeneric("s4Crossed", function(x, y) standardGeneric("s4Crossed"))
methods::setMethod("s4Crossed", c("Left", "ANY"), function(x, y) "left")
methods::setMethod("s4Crossed", c("ANY", "Right"), function(x, y) "right")
methods::setGeneric("s4Equal", function(x) standardGeneric("s4Equal"))
methods::setMethod("s4Equal", "Left", function(x) "left")
methods::setMethod("s4Equal", "Right", function(x) "right")

methods::setClassUnion("Either", c("DistanceRoot", "NULL"))
methods::setGeneric("s4Union", function(x) standardGeneric("s4Union"))
methods::setMethod("s4Union", "Either", function(x) "union")
methods::setOldClass(c("OldChild", "OldParent"))
methods::setGeneric("s4Old", function(x) standardGeneric("s4Old"))
methods::setMethod("s4Old", "OldParent", function(x) "old")

Ref <- methods::setRefClass("Ref", contains = "DistanceRoot", fields = list(field = "numeric"))
RefChild <- methods::setRefClass("RefChild", contains = "Ref")
methods::setGeneric("s4Reference", function(x) standardGeneric("s4Reference"))
methods::setMethod("s4Reference", "DistanceRoot", function(x) "storage")
methods::setGeneric("s4Environment", function(x) standardGeneric("s4Environment"))
methods::setMethod("s4Environment", "envRefClass", function(x) "reference")

methods::setMethod("length", "DistanceRoot", function(x) 1L)
methods::setMethod("Ops", c("DistanceRoot", "DistanceRoot"), function(e1, e2) 10)
methods::setMethod("Arith", c("DistanceRoot", "DistanceRoot"), function(e1, e2) 20)
methods::setMethod("+", c("DistanceRoot", "DistanceRoot"), function(e1, e2) 30)

methods::setGeneric("s4Next", function(x) standardGeneric("s4Next"))
methods::setMethod("s4Next", "DistanceRoot", function(x) "root")
methods::setMethod("s4Next", "DistanceChild", function(x) methods::callNextMethod("changed"))
methods::setGeneric("s4Default", function(x) "default")
methods::setMethod("s4Default", "ANY", function(x) "registered")
